// DEV-ONLY mock engine (`npm run dev -- --mode mock`). Everything here is synthetic: a fake file tree
// and a procedurally drawn phantom head generated by `scripts/make-mock-study.mjs` into `public/mock/`.
import { ApiError, type JobInfo, type ProgressEvent } from './client'
import { normaliseOptions, type FsListing, type FsRoot, type ImportRequest, type InspectResult, type Knowledge, type ModelBundle, type ModelRequest, type ModelsInfo, type StudyInfo, type StudySummary } from './endpoints'

const DISC = '/demo-disc'
const HOME = '/home/demo'

export async function mockRoots(): Promise<FsRoot[]> {
  await sleep(120)
  return [
    { path: DISC, label: 'Demo disc (synthetic)', kind: 'removable' },
    { path: HOME, label: 'Home', kind: 'home' },
  ]
}

const TREE: Record<string, FsListing> = {
  [DISC]: {
    path: DISC, parent: null, entries: [
      { name: 'PHANTOM_HEAD', path: `${DISC}/PHANTOM_HEAD`, kind: 'dir', size: null, hint: 'dicomdir' },
      { name: 'LOCKED_DISC', path: `${DISC}/LOCKED_DISC`, kind: 'dir', size: null, hint: 'dcmburner' },
      { name: 'EMPTY_FOLDER', path: `${DISC}/EMPTY_FOLDER`, kind: 'dir', size: null },
      { name: 'xray-unknown.7z', path: `${DISC}/xray-unknown.7z`, kind: 'file', size: 18_400_000 },
    ],
  },
  [`${DISC}/PHANTOM_HEAD`]: { path: `${DISC}/PHANTOM_HEAD`, parent: DISC, entries: [{ name: 'DICOM', path: `${DISC}/PHANTOM_HEAD/DICOM`, kind: 'dir', size: null }] },
  [`${DISC}/LOCKED_DISC`]: { path: `${DISC}/LOCKED_DISC`, parent: DISC, entries: [{ name: 'dcmdata.enc', path: `${DISC}/LOCKED_DISC/dcmdata.enc`, kind: 'file', size: 92_000_000 }] },
  [HOME]: {
    path: HOME, parent: null, entries: [
      { name: 'Downloads', path: `${HOME}/Downloads`, kind: 'dir', size: null },
      { name: 'Documents', path: `${HOME}/Documents`, kind: 'dir', size: null },
    ],
  },
  [`${HOME}/Downloads`]: { path: `${HOME}/Downloads`, parent: HOME, entries: [{ name: 'phantom-study.zip', path: `${HOME}/Downloads/phantom-study.zip`, kind: 'file', size: 41_000_000 }] },
}

export async function mockList(path: string): Promise<FsListing> {
  await sleep(150)
  const hit = TREE[path.replace(/\/+$/, '')]
  if (hit) return hit
  const parent = path.includes('/') ? path.slice(0, path.lastIndexOf('/')) || null : null
  return { path, parent, entries: [] }
}

export async function mockInspect(path: string): Promise<InspectResult> {
  await sleep(350)
  if (/LOCKED|\.enc$/i.test(path)) return { adapter: 'dcmburner', label: 'Encrypted hospital disc', encrypted: true, confidence: 0.96, notes: ['The images are locked with the password printed on your hospital slip.'] }
  if (/EMPTY/i.test(path)) return { adapter: 'loose', label: 'Folder', encrypted: false, confidence: 0.2, notes: [] }
  if (/\.7z$/i.test(path)) return { adapter: null, label: 'Unrecognised archive', encrypted: false, confidence: 0.1, notes: [] }
  if (/\.zip$/i.test(path)) return { adapter: 'loose', label: 'ZIP archive with DICOM files', encrypted: false, confidence: 0.8, notes: [] }
  return { adapter: 'dicomdir', label: 'Standard DICOM disc (DICOMDIR)', encrypted: false, confidence: 0.98, notes: [] }
}

interface MockJob { info: JobInfo; req: ImportRequest; timers: number[]; onEnd?: (j: JobInfo) => void }
const jobs = new Map<string, MockJob>()

export async function mockImport(req: ImportRequest): Promise<JobInfo> {
  await sleep(120)
  const info: JobInfo = { id: 'mock-' + Math.random().toString(36).slice(2, 9), kind: 'import', status: 'running', stage: 'detect', pct: 0, created: new Date().toISOString() }
  jobs.set(info.id, { info, req, timers: [] })
  return info
}

export function mockWatch(id: string, onEvent: (e: ProgressEvent) => void, onEnd: (j: JobInfo) => void): () => void {
  const job = jobs.get(id)
  if (!job) { onEnd({ id, kind: 'import', status: 'failed', stage: '', pct: 0, error: 'unknown job', created: new Date().toISOString() }); return () => {} }
  job.onEnd = onEnd
  if (job.info.kind === 'model') return watchModel(job, onEvent)
  if (job.info.kind === 'models') return watchPull(job, onEvent)
  const { path, password } = job.req
  const encrypted = /LOCKED|\.enc$/i.test(path)
  let fail: { at: string; code: string; error: string } | null = null
  if (encrypted && !password) fail = { at: 'decrypt', code: 'password_required', error: 'This disc is encrypted.' }
  else if (encrypted && password !== 'phantom') fail = { at: 'decrypt', code: 'wrong_password', error: 'The password did not unlock the disc.' }
  else if (/EMPTY/i.test(path)) fail = { at: 'scan', code: 'no_images', error: 'No medical images were found.' }
  else if (/\.7z$/i.test(path)) fail = { at: 'detect', code: 'unsupported', error: 'Unrecognised disc format.' }

  const stages = ['detect', ...(encrypted ? ['decrypt'] : []), 'extract', 'scan', 'group', 'classify', 'export']
  let seq = 0
  let t = 0
  for (let s = 0; s < stages.length; s++) {
    const stage = stages[s]
    for (let k = 0; k < 3; k++) {
      t += 260
      const pct = Math.round(((s + (k + 1) / 3) / stages.length) * 100)
      job.timers.push(window.setTimeout(() => {
        job.info = { ...job.info, stage, pct }
        onEvent({ seq: seq++, stage, pct, msg: '', level: 'info', ts: Date.now() / 1000 })
      }, t))
    }
    if (fail && fail.at === stage) {
      const f = fail
      job.timers.push(window.setTimeout(() => finish(job, { status: 'failed', error: f.error, result: { code: f.code, adapter: encrypted ? 'dcmburner' : null } }), t + 200))
      return () => clear(job)
    }
  }
  job.timers.push(window.setTimeout(() => finish(job, { status: 'done', pct: 100, result: { study_id: 'phantom' } }), t + 300))
  return () => clear(job)
}

export async function mockCancel(id: string): Promise<void> {
  const job = jobs.get(id)
  if (!job) return
  clear(job)
  await sleep(150)
  finish(job, { status: 'cancelled' })
}

function finish(job: MockJob, patch: Partial<JobInfo>) {
  clear(job)
  job.info = { ...job.info, ...patch, ended: new Date().toISOString() }
  job.onEnd?.(job.info)
  jobs.delete(job.info.id)
}
function clear(job: MockJob) { job.timers.forEach((x) => clearTimeout(x)); job.timers = [] }

// ---------- 3D model (synthetic phantoms; files written by make-mock-study.mjs) ----------
const BUILT = 'mmr-mock-model-built:'
/** The synthetic model files always exist; pretend each is unbuilt until the user clicks "Build" once per session. */
export function mockModelBuilt(studyId: string): boolean {
  try { return sessionStorage.getItem(BUILT + studyId) === '1' || new URLSearchParams(location.search).has('built') } catch { return true }
}

/** `GET /api/studies/{id}/model/options` (contract §6), from `studies/<id>/options.json`; null = route absent. */
export async function mockModelOptions(studyId: string): Promise<unknown> {
  await sleep(150)
  const r = await fetch(`/mock/studies/${encodeURIComponent(studyId)}/options.json`)
  if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) return null
  return r.json()
}

export async function mockStartModel(studyId: string, body: ModelRequest = {}): Promise<JobInfo> {
  await sleep(120)
  const raw = await mockModelOptions(studyId)
  const opts = raw == null ? null : normaliseOptions(raw)
  if (opts && body.pipeline && body.pipeline !== 'auto' && !opts.pipelines.some((x) => x.pipeline === body.pipeline)) throw new ApiError(422, 'Unknown pipeline')
  const p = opts?.pipelines.find((x) => x.pipeline === body.pipeline) ?? opts?.pipelines[0]
  const b = body.backend ? p?.backends.find((x) => x.id === body.backend) : null
  if (body.backend && p && (!b || !b.available)) throw new ApiError(422, b?.reason ?? 'Backend not available')
  const info: JobInfo = { id: 'mock-model-' + Math.random().toString(36).slice(2, 9), kind: 'model', status: 'running', stage: 'plan', pct: 0, created: new Date().toISOString() }
  jobs.set(info.id, { info, req: { path: studyId }, timers: [] })
  return info
}

function watchModel(job: MockJob, onEvent: (e: ProgressEvent) => void): () => void {
  const stages = ['plan', 'load', 'fuse', 'segment', 'surface', 'measure', 'thumbs', 'export']
  let seq = 0, t = 0
  stages.forEach((stage, s) => {
    for (let k = 0; k < 2; k++) {
      t += 220
      const pct = Math.round(((s + (k + 1) / 2) / stages.length) * 100)
      job.timers.push(window.setTimeout(() => {
        job.info = { ...job.info, stage, pct }
        onEvent({ seq: seq++, stage, pct, msg: '', level: 'info', ts: Date.now() / 1000 })
      }, t))
    }
  })
  job.timers.push(window.setTimeout(() => {
    try { sessionStorage.setItem(BUILT + job.req.path, '1') } catch { /* ignore */ }
    finish(job, { status: 'done', pct: 100, result: { model: 'model/' } })
  }, t + 250))
  return () => clear(job)
}

// ---------- model downloads (simulated: nothing is fetched) ----------
// `?models=none|atlas|synthseg|offline|fail` picks the starting state; downloads are remembered per tab.
const MODELS_KEY = 'mmr-mock-models'
const MB = 1_000_000
const MOCK_BUNDLES: { id: string; title: string; enables: string; host: string; licence: string; attribution: string; files: [string, number, string][]; pipelines: string[] }[] = [
  { id: 'atlas-ho', title: 'Brain atlas (basic)', enables: 'Basic brain labels: a standard brain atlas is fitted to your T1 scan to name its main regions.', host: 'templateflow.s3.amazonaws.com',
    licence: 'Harvard-Oxford atlases: CC BY-SA 4.0; MNI ICBM152 2009c (permissive, with notice)', attribution: 'Harvard-Oxford atlases (FSL); ICBM 2009c template (McConnell Brain Imaging Centre); via TemplateFlow.',
    files: [['mni152-2009c-t1', 13_685_075, 'MNI template'], ['mni152-2009c-brain-mask', 159_538, 'Brain mask'], ['ho-cortical-lat', 326_295, 'Cortical atlas'], ['ho-subcortical', 301_870, 'Subcortical atlas']], pipelines: ['brain_mr'] },
  { id: 'synthseg', title: 'SynthSeg brain AI', enables: 'Better brain labels: detailed regions on any MRI type, including thick-slice scans.', host: 'github.com',
    licence: 'Apache-2.0 (SynthSeg code; weights distributed with it)', attribution: 'SynthSeg 2.0, B. Billot et al., Medical Image Analysis 2023; PNAS 2023.',
    files: [['synthseg-seg', 53_033_940, 'Segmentation'], ['synthseg-parc', 53_090_350, 'Parcellation'], ['synthseg-robust', 214_380_627, 'Robust model']], pipelines: ['brain_mr'] },
  { id: 'totalseg', title: 'TotalSegmentator body AI', enables: 'Detailed CT body models: 117 organs, bones and vessels.', host: 'github.com',
    licence: 'Apache-2.0', attribution: 'TotalSegmentator, J. Wasserthal et al., Radiology: AI 2023.',
    files: [['totalseg-total-fast', 135_386_075, 'Body weights']], pipelines: ['ct_body'] },
]
function mockParam(): string { try { return new URLSearchParams(location.search).get('models') ?? 'none' } catch { return 'none' } }
function mockInstalled(): Set<string> {
  let saved: string[] = []
  try { saved = JSON.parse(sessionStorage.getItem(MODELS_KEY) ?? '[]') } catch { /* ignore */ }
  const start = mockParam()
  return new Set([...saved, ...(start === 'atlas' || start === 'synthseg' ? ['atlas-ho'] : []), ...(start === 'synthseg' ? ['synthseg'] : [])])
}
export async function mockModels(): Promise<ModelsInfo> {
  await sleep(120)
  const have = mockInstalled()
  const bundles: ModelBundle[] = MOCK_BUNDLES.map((b) => {
    const size = b.files.reduce((a, f) => a + f[1], 0)
    const inst = have.has(b.id)
    const usable = b.id !== 'totalseg'
    return {
      id: b.id, title: b.title, enables: b.enables, size, download_size: inst ? 0 : size, installed: inst, partial: false, usable,
      needs: usable ? null : "Needs the TotalSegmentator add-on: uv tool install --reinstall 'medmereport[totalseg]'",
      pipelines: b.pipelines, hosts: [b.host], credits: [{ licence: b.licence, attribution: b.attribution }],
      assets: b.files.map(([name, sz, description]) => ({ name, size: sz, description, installed: inst, host: b.host })),
    }
  })
  const state = have.has('synthseg') ? 'synthseg' : have.has('atlas-ho') ? 'atlas' : 'none'
  return { offline: mockParam() === 'offline', bundles, brain: { state, suggest: state === 'synthseg' ? null : 'synthseg' } }
}
export async function mockPull(bundle: string): Promise<JobInfo> {
  await sleep(120)
  if (mockParam() === 'offline') throw new ApiError(403, 'Model downloads are turned off on this computer (MEDMEREPORT_OFFLINE=1).')
  if (!MOCK_BUNDLES.some((b) => b.id === bundle)) throw new ApiError(404, 'Unknown model bundle')
  const info: JobInfo = { id: 'mock-models-' + Math.random().toString(36).slice(2, 9), kind: 'models', status: 'running', stage: 'download', pct: 0, created: new Date().toISOString() }
  jobs.set(info.id, { info, req: { path: bundle }, timers: [] })
  return info
}
function watchPull(job: MockJob, onEvent: (e: ProgressEvent) => void): () => void {
  const b = MOCK_BUNDLES.find((x) => x.id === job.req.path)
  const total = b ? b.files.reduce((a, f) => a + f[1], 0) : 1
  const steps = 24
  for (let i = 1; i <= steps; i++) {
    job.timers.push(window.setTimeout(() => {
      const pct = Math.min(99.9, (100 * i) / steps)
      job.info = { ...job.info, stage: 'download', pct }
      onEvent({ seq: i, stage: i === steps ? 'verify' : 'download', pct, msg: `${((total * i) / steps / MB).toFixed(1)} / ${(total / MB).toFixed(1)} MB`, level: 'info', ts: Date.now() / 1000 })
    }, i * 170))
  }
  job.timers.push(window.setTimeout(() => {
    if (mockParam() === 'fail') return finish(job, { status: 'failed', error: 'checksum mismatch', result: { code: 'checksum_mismatch' } })
    try { sessionStorage.setItem(MODELS_KEY, JSON.stringify([...mockInstalled(), job.req.path])) } catch { /* ignore */ }
    finish(job, { status: 'done', pct: 100, result: { bundle: job.req.path } })
  }, steps * 170 + 300))
  return () => clear(job)
}

export async function mockKnowledge(lang: string): Promise<Knowledge | null> {
  // one English document with embedded `i18n.hi` variants (exercises the fallback path)
  return lang === 'en' ? getJSON<Knowledge>('/mock/knowledge.json') : null
}

async function getJSON<T>(url: string): Promise<T> {
  const r = await fetch(url)
  if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) {
    throw new Error('Mock data missing — run `node scripts/make-mock-study.mjs` in web/.')
  }
  return r.json() as Promise<T>
}
export const mockStudies = () => getJSON<StudySummary[]>('/mock/studies.json')
export const mockStudy = (id: string) => getJSON<StudyInfo>(`/mock/studies/${encodeURIComponent(id)}/study.json`)

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))
